// Python-style formatting helpers (no imports).

export function formatBool(v) {
  return v ? 'True' : 'False';
}

export function formatFloat(x) {
  if (Number.isInteger(x)) return `${x}.0`;
  return String(x);
}

export function formatPathLength(result) {
  return result.zeroInteger ? '0' : formatFloat(result.length);
}

export function formatNodeList(nodes) {
  return `[${nodes.map((n) => String(n)).join(', ')}]`;
}

export function formatEdgeList(edges) {
  return `[${edges.map(([u, v]) => `(${String(u)}, ${String(v)})`).join(', ')}]`;
}

// argparse-compatible CLI parsing (no imports).

const FLAGS = ['--a', '--b', '--c', '--d', '--e'];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C --d D --e E\n`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n' +
    '  --c C\n' +
    '  --d D\n' +
    '  --e E\n'
  );
}

function errorText(prog, message) {
  return usageLine(prog) + `${prog}: error: ${message}\n`;
}

// Python int() semantics: surrounding whitespace stripped, optional sign,
// digits with single underscores allowed only between digits.
function parsePythonInt(raw) {
  const s = raw.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g, '');
  if (!/^[+-]?\d(_?\d)*$/.test(s)) return null;
  return BigInt(s.replace(/_/g, ''));
}

// argparse treats a token starting with '-' as an option string unless it
// looks like a negative number (no option strings look like negative numbers).
function looksLikeOption(token) {
  return token.startsWith('-') && !/^-\d+$|^-\d*\.\d+$/.test(token);
}

export function parseCli(argv, prog) {
  const values = new Map();
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', text: helpText(prog) };
    }

    let flag = null;
    let raw = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        const name = token.slice(0, eq);
        if (FLAGS.includes(name)) {
          flag = name;
          raw = token.slice(eq + 1);
        }
      } else if (FLAGS.includes(token)) {
        flag = token;
        if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
          return {
            kind: 'error',
            text: errorText(prog, `argument ${flag}: expected one argument`),
          };
        }
        raw = argv[++i];
      }
    }

    if (flag === null) {
      extras.push(token);
      continue;
    }

    const value = parsePythonInt(raw);
    if (value === null) {
      return {
        kind: 'error',
        text: errorText(prog, `argument ${flag}: invalid int value: '${raw}'`),
      };
    }
    values.set(flag, value); // duplicates: last wins
  }

  const missing = FLAGS.filter((f) => !values.has(f));
  if (missing.length > 0) {
    return {
      kind: 'error',
      text: errorText(
        prog,
        `the following arguments are required: ${missing.join(', ')}`
      ),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      text: errorText(prog, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    args: {
      a: values.get('--a'),
      b: values.get('--b'),
      c: values.get('--c'),
      d: values.get('--d'),
      e: values.get('--e'),
    },
  };
}

args.command:
node --input-type=module -e "
import {formatBool, formatFloat, formatPathLength, formatNodeList, formatEdgeList} from '/output/lib/pyformat.mjs';
import {parseCli} from '/output/lib/cli.mjs';
const assert=(c,m)=>{if(!c)throw new Error(m)};
assert(formatBool(true)==='True'&&formatBool(false)==='False','bool');
assert(formatFloat(5)==='5.0'&&formatFloat(0)==='0.0','float');
assert(formatPathLength({length:0,zeroInteger:true})==='0','pl0');
assert(formatPathLength({length:4,zeroInteger:false})==='4.0','pl4');
assert(formatNodeList([1n,5n])==='[1, 5]','nl');
assert(formatEdgeList([[1n,2n],[1n,5n]])==='[(1, 2), (1, 5)]','el');
const prog='test10.mjs';
let r=parseCli(['--a','1','--b=2','--c','-3','--d','+007','--e','1_0'],prog);
assert(r.kind==='ok'&&r.args.a===1n&&r.args.b===2n&&r.args.c===-3n&&r.args.d===7n&&r.args.e===10n,'ok');
r=parseCli(['--a','1','--a','9','--b','2','--c','3','--d','4','--e','5'],prog);
assert(r.kind==='ok'&&r.args.a===9n,'dup last-wins');
r=parseCli(['-h'],prog);
assert(r.kind==='help'&&r.text==='usage: test10.mjs [-h] --a A --b B --c C --d D --e E\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n  --d D\n  --e E\n','help text');
r=parseCli(['--a','1'],prog);
assert(r.kind==='error'&&r.text==='usage: test10.mjs [-h] --a A --b B --c C --d D --e E\ntest10.mjs: error: the following arguments are required: --b, --c, --d, --e\n','missing');
r=parseCli(['--a','x','--b','2','--c','3','--d','4','--e','5'],prog);
assert(r.kind==='error'&&r.text.includes(\"argument --a: invalid int value: 'x'\"),'invalid');
r=parseCli(['--a','1_','--b','2','--c','3','--d','4','--e','5'],prog);
assert(r.kind==='error'&&r.text.includes(\"invalid int value: '1_'\"),'bad underscore');
r=parseCli(['--a'],prog);
assert(r.kind==='error'&&r.text.includes('argument --a: expected one argument'),'missing value');
r=parseCli(['--a','--b','1'],prog);
assert(r.kind==='error'&&r.text.includes('argument --a: expected one argument'),'option-like value');
r=parseCli(['--a','1','--b','2','--c','3','--d','4','--e','5','--foo','bar'],prog);
assert(r.kind==='error'&&r.text.includes('unrecognized arguments: --foo bar'),'extras');
r=parseCli(['--a','-5','--b','2','--c','3','--d','4','--e','5'],prog);
assert(r.kind==='ok'&&r.args.a===-5n,'negative value');
r=parseCli(['--a',' -0 ','--b','2','--c','3','--d','4','--e','5'],prog);
assert(r.kind==='ok'&&r.args.a===0n,'ws/-0 normalize');
console.log('all assertions passed');
"
